public class OverflowDemoTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("sumAsInt(2, 3)", 5, OverflowDemo.sumAsInt(2, 3));
        check("sumAsInt(-4, 10)", 6, OverflowDemo.sumAsInt(-4, 10));
        check("sumAsInt(Integer.MAX_VALUE, 1) wraps", Integer.MIN_VALUE,
                OverflowDemo.sumAsInt(Integer.MAX_VALUE, 1));
        check("sumAsLong(2, 3)", 5L, OverflowDemo.sumAsLong(2, 3));
        check("sumAsLong(Integer.MAX_VALUE, 1)", 2147483648L,
                OverflowDemo.sumAsLong(Integer.MAX_VALUE, 1));
        check("sumAsLong(Integer.MAX_VALUE, Integer.MAX_VALUE)", 4294967294L,
                OverflowDemo.sumAsLong(Integer.MAX_VALUE, Integer.MAX_VALUE));
        check("sumAsLong(Integer.MIN_VALUE, -1)", -2147483649L,
                OverflowDemo.sumAsLong(Integer.MIN_VALUE, -1));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

